  Archive, ArrowLeft, ArrowRight, BookOpen, Bot, Check, ChevronLeft, ChevronRight,
  Clock3, FileText, FolderOpen, GitBranch, Info, Library, Menu, MoreHorizontal,
  Pause, Play, Plus, Scale, ShieldCheck, Sparkles, Target, X,
} from "lucide-vue-next";

const view = ref("home");
const mobileMenuOpen = ref(false);
const drawerOpen = ref(false);
const showNotice = ref(false);
const dialog = ref(null);
const creationReturnView = ref("shelf");

const creationType = ref("future");
const form = ref({ direction: "", goal: "", action: "", alternative: "", facts: "", limits: "" });
const sourceConsent = ref({ court: true, polarizer: true, profile: false });
const pace = ref("normal");

const sourceCases = ref([
  { id: "court-018", title: "是否离开稳定工作", time: "2025 年 4 月", actual: "留在原团队", alternative: "加入创业团队", facts: "已有三个月生活缓冲，也收到创业团队的邀请。", limits: "需要完成交接，现金流只能支撑有限时间。", status: "已决定" },
  { id: "court-012", title: "是否搬去另一个城市", time: "2023 年 9 月", actual: "继续留在上海", alternative: "搬去另一座城市", facts: "当时同时存在新的工作机会和迁居条件。", limits: "需要重新建立工作和生活支持。", status: "已决定" },
]);
const selectedSource = ref("court-018");
const selectedCase = ref(null);
const caseFormOpen = ref(false);
const caseForm = ref({ title: "", time: "", actual: "", alternative: "", facts: "", limits: "" });

const courtSessionOpen = ref(false);
const courtStage = ref(0);
const courtResponse = ref("");
const courtStageAccepted = ref([false, false, false]);
const courtStageContinued = ref(false);
const courtStages = [
  { name: "事实", title: "当时发生了什么", goal: "还原时间、处境、资源和现实限制。", question: "在这个选择变得重要时，你当时已经知道什么？还有什么不确定？" },
  { name: "路径", title: "当时有哪些路", goal: "说明每条路当时需要什么、放弃什么。", question: "除了现实中走过的路，当时还有哪一条路径确实可以执行？" },
  { name: "判断", title: "为什么这样选", goal: "找出真正起作用的理由和默认前提。", question: "当时真正起作用的判断是什么？它保护了什么，又让你放弃了什么？" },
];

const polarizerSessionOpen = ref(false);
const polarizerTopic = ref(0);
const polarizerResponse = ref("");
const polarizerResponses = ref([]);
const polarizerStance = ref("");
const polarizerAuthorized = ref(true);
const polarizerClaim = ref("没有足够准备，就不应该离职。");
const polarizerClaimType = ref("情境判断");
const polarizerTopics = [
  { name: "定义", challenge: "你说的“足够准备”具体指什么？哪些条件算准备，哪些只是让你感觉更安全？" },
  { name: "范围", challenge: "这条判断适用于所有离职场景吗？在什么场景下它可能并不适用？" },
  { name: "证据", challenge: "哪些亲身经历或依据支撑这条判断？你是否把一次结果扩大成了普遍结论？" },
  { name: "反例", challenge: "什么事实出现时，会让你承认这条命题在某个场景中失效？" },
  { name: "更新", challenge: "如果出现新的事实，你愿意如何限制、修正或重新表述这条命题？" },
];

const universes = ref([
  { id: "017", title: "加入创业团队之后", type: "历史分叉", status: "等待你的决定", statusKey: "waiting", cover: "indigo", origin: "从 2025 年 4 月的选择点展开", currentTime: "2027 年第二季度", state: "你在一个 12 人团队中负责产品与工程协作；试运行已持续四个月，现金流还可支撑两个季度。", sources: ["决策法庭 · CASE 018", "允许使用的起始资料"], events: [
    { id: "evt-01", time: "2025 年 4 月", title: "离开前的那一周", body: "你在交接清单上写下最后一项工作。原团队给出了更明确的职责边界，但你仍按此前确认的计划，加入了朋友正在组建的创业团队。", action: "你接受了创业团队的邀请。" },
    { id: "evt-02", time: "2025 年 8 月", title: "第一个可用版本", body: "产品没有如期获得第一批付费用户，但一间小型工作室愿意连续两周试用。你开始把分散的需求记录成每周一次的访谈。", action: "平行的你决定先完成试用闭环。" },
    { id: "evt-03", time: "2026 年 3 月", title: "一张更小的桌子", body: "团队缩减了办公空间。你接手了原本由两个人分担的客户沟通，工作节奏比预期更碎，但每周仍保留半天处理产品的长期问题。", action: "你把客户问题整理为固定的优先级清单。" },
    { id: "evt-04", time: "2027 年第二季度", title: "全职邀请", body: "一位长期合作的客户提出全职邀请，希望你负责其内部工具的重构。邀请能立即改善现金流，也意味着你要暂时离开当前团队的核心推进。对方要求在两周内给出答复。", action: null, pending: true },
  ] },
  { id: "016", title: "把研究写成产品", type: "未来选择", status: "离线推演已达到步数", statusKey: "offline", cover: "forest", origin: "从 2026 年 8 月的当前选择开始", currentTime: "2028 年", state: "你保留了独立研究的节奏，并与两位同行维持着固定的月度审阅。", sources: ["未来选择起始输入"], events: [
    { id: "evt-11", time: "2026 年 8 月", title: "公开的第一篇", body: "你把一直在内部使用的方法写成公开文章，并邀请三位同行提出反例。", action: "你选择先公开一个可讨论的版本。" },
    { id: "evt-12", time: "2027 年", title: "读者来信", body: "文章被一间独立工作室采用，合作从一次讨论逐渐变成稳定的共同研究。", action: "平行的你决定维持小规模合作。" },
  ] },
  { id: "011", title: "向西的窗口", type: "历史分叉", status: "已完结，只读", statusKey: "complete", cover: "wine", origin: "从 2023 年 9 月的选择点展开", currentTime: "2026 年", state: "档案已封存。最后一项计划在宇宙内已自然结束。", sources: ["决策法庭 · CASE 012"], events: [{ id: "evt-21", time: "2023 年 9 月", title: "另一座城市", body: "你接受了迁居的机会，开始重新建立工作与生活的边界。", action: "你搬往新的城市。" }] },
]);
const activeUniverse = ref(universes.value[0]);
const activeEventId = ref("evt-04");
const activeEvent = computed(() => activeUniverse.value.events.find((event) => event.id === activeEventId.value) || activeUniverse.value.events.at(-1));
const selectedCaseData = computed(() => sourceCases.value.find((item) => item.id === selectedSource.value));

const decisionMode = ref(null);
const actionIndex = ref(0);
const customAction = ref("");
const actionCards = [
  { title: "接受邀请", text: "在约定期限内加入，并完成当前团队的交接。" },
  { title: "提出阶段性合作", text: "保留现有位置，以明确的周期和边界参与对方项目。" },
  { title: "暂不接受", text: "说明当前承诺，继续推进已经开始的工作。" },
  { title: "自定义方向", text: "写下此刻真正准备采取的行动。", custom: true },
];
const stateOpen = ref(false);
const sourcesOpen = ref(false);
const supplementalOpen = ref(false);
const supplementalText = ref("");
const offlineOpen = ref(false);
const offlineSteps = ref(3);
const offlineRunning = ref(false);

const routeViews = new Set(["home", "shelf", "court", "polarizer", "create", "confirm", "universe"]);
let syncingRoute = false;

function routeFromHash() {
  const route = window.location.hash.replace(/^#\/?/, "");
  return routeViews.has(route) ? route : "home";
}
function navigate(nextView) {
  view.value = nextView;
  mobileMenuOpen.value = false;
  if (window.location.hash !== `#/${nextView}`) window.location.hash = `#/${nextView}`;
}
function syncViewFromRoute() {
  const nextView = routeFromHash();
  syncingRoute = true;
  view.value = nextView;
  syncingRoute = false;
}
watch(view, (nextView) => {
  if (syncingRoute || !routeViews.has(nextView)) return;
  const nextHash = `#/${nextView}`;
  if (window.location.hash !== nextHash) window.location.hash = nextHash;
}, { flush: "sync" });
onMounted(() => { if (window.location.hash) syncViewFromRoute(); else window.history.replaceState(null, "", "#/home"); window.addEventListener("hashchange", syncViewFromRoute); });
onBeforeUnmount(() => window.removeEventListener("hashchange", syncViewFromRoute));

function openUniverse(universe) { activeUniverse.value = universe; activeEventId.value = universe.events.at(-1).id; decisionMode.value = null; navigate("universe"); }
function beginCreate(type, returnView = view.value) { creationReturnView.value = returnView; creationType.value = type; form.value = { direction: "", goal: "", action: "", alternative: "", facts: "", limits: "" }; navigate("create"); }
function openConfirm() { if (creationType.value === "future" && (!form.value.direction || !form.value.goal || !form.value.action)) return; if (creationType.value === "history" && !selectedCaseData.value) return; navigate("confirm"); }
function createUniverse() {
  const title = creationType.value === "future" ? form.value.direction : `${selectedCaseData.value.title}之后`;
  const universe = { id: String(Math.max(...universes.value.map((item) => Number(item.id))) + 1).padStart(3, "0"), title, type: creationType.value === "future" ? "未来选择" : "历史分叉", status: "运行中", statusKey: "running", cover: "umber", origin: creationType.value === "future" ? "从现在的选择点展开" : `从 ${selectedCaseData.value.time} 的选择点展开`, currentTime: "起点", state: "宇宙已建立，时间线将从确认的起点开始发展。", sources: [...(creationType.value === "history" && sourceConsent.value.court ? [`决策法庭 · ${selectedCaseData.value.id.toUpperCase()}`] : []), ...(creationType.value === "future" ? ["未来选择起始输入"] : []), ...(sourceConsent.value.polarizer ? ["个人偏见偏振器 · 已授权材料"] : []), ...(sourceConsent.value.profile ? ["其他已允许的个人资料"] : [])], events: [{ id: `evt-${Date.now()}`, time: creationType.value === "future" ? "现在" : selectedCaseData.value.time, title: "推演即将开始", body: "起点资料已经写入这条独立的时间线。下一步推演会生成第一个事件。", action: creationType.value === "future" ? `准备开始：${form.value.action}` : `你选择了${selectedCaseData.value.alternative || "一条当时可行的未选路径"}。` }] };
  universes.value.unshift(universe); activeUniverse.value = universe; activeEventId.value = universe.events[0].id; navigate("universe");
}
function openCase(item) { selectedSource.value = item.id; selectedCase.value = item; }
function saveCase() { if (!caseForm.value.title || !caseForm.value.time || !caseForm.value.actual || !caseForm.value.alternative) return; const id = `court-${Date.now()}`; sourceCases.value.unshift({ id, ...caseForm.value, status: "已决定" }); selectedSource.value = id; selectedCase.value = sourceCases.value[0]; caseForm.value = { title: "", time: "", actual: "", alternative: "", facts: "", limits: "" }; caseFormOpen.value = false; }
function startCourt(item = selectedCaseData.value) { if (!item) return; selectedSource.value = item.id; courtStage.value = 0; courtResponse.value = ""; courtStageAccepted.value = [false, false, false]; courtStageContinued.value = false; courtSessionOpen.value = true; selectedCase.value = null; }
function continueCourtStage() { if (!courtResponse.value.trim()) return; courtStageContinued.value = true; }
function acceptCourtStage() { if (!courtResponse.value.trim() && !courtStageContinued.value) return; courtStageAccepted.value[courtStage.value] = true; if (courtStage.value < 2) { courtStage.value += 1; courtResponse.value = ""; courtStageContinued.value = false; } else { courtSessionOpen.value = false; const item = selectedCaseData.value; item.status = "已决定"; item.courtComplete = true; dialog.value = "court-complete"; } }

function startPolarizer() { if (!polarizerClaim.value.trim()) return; polarizerSessionOpen.value = true; polarizerTopic.value = 0; polarizerResponse.value = ""; polarizerResponses.value = []; polarizerStance.value = ""; }
function continuePolarizer() { if (!polarizerResponse.value.trim()) return; polarizerResponses.value.push({ topic: polarizerTopics[polarizerTopic.value].name, response: polarizerResponse.value }); if (polarizerTopic.value < polarizerTopics.length - 1) { polarizerTopic.value += 1; polarizerResponse.value = ""; } else { polarizerSessionOpen.value = false; dialog.value = "polarizer-finish"; } }
function savePolarizerResult() { if (!polarizerStance.value) return; polarizerSessionOpen.value = false; dialog.value = "polarizer-saved"; }

function continueSimulation({ offline = false } = {}) { const universe = activeUniverse.value; if (universe.statusKey === "complete" || (universe.statusKey === "offline" && offlineRunning.value && !offline)) return; const next = universe.events.length + 1; const event = { id: `evt-${Date.now()}`, time: "几周后", title: "新的工作节奏", body: "一段时间过去了。已经开始的事项仍在推进，你根据已有资源调整了每周的安排；新的外部变化暂时没有改变这条时间线的基本方向。", action: "平行的你维持了当前计划。" }; universe.events.push(event); universe.currentTime = `第 ${next} 个事件之后`; universe.status = offline ? "离线推演中" : "运行中"; universe.statusKey = offline ? "offline" : "running"; activeEventId.value = event.id; }
function chooseParallel() { activeEvent.value.action = "平行的你决定提出阶段性合作，并保留当前团队的推进。"; activeEvent.value.pending = false; activeUniverse.value.status = "运行中"; activeUniverse.value.statusKey = "running"; decisionMode.value = null; }
function confirmAction() { const card = actionCards[actionIndex.value]; if (card.custom && !customAction.value.trim()) return; activeEvent.value.action = card.custom ? customAction.value : `你选择${card.title}。`; activeEvent.value.pending = false; activeUniverse.value.status = "运行中"; activeUniverse.value.statusKey = "running"; decisionMode.value = null; customAction.value = ""; }
function addCurrentFact() { if (!supplementalText.value.trim()) return; activeUniverse.value.state = `${activeUniverse.value.state} ${supplementalText.value.trim()}`; supplementalText.value = ""; supplementalOpen.value = false; dialog.value = "fact-saved"; }
function startOffline() { offlineRunning.value = true; activeUniverse.value.status = "离线推演中"; activeUniverse.value.statusKey = "offline"; offlineOpen.value = false; window.setTimeout(() => { for (let i = 0; i < offlineSteps.value; i += 1) continueSimulation({ offline: true }); offlineRunning.value = false; if (activeUniverse.value.statusKey === "offline") { activeUniverse.value.status = "离线推演已达到步数"; activeUniverse.value.statusKey = "offline"; } }, 450); }
function pauseUniverse() { activeUniverse.value.status = "暂停"; activeUniverse.value.statusKey = "paused"; }
function resumeUniverse() { activeUniverse.value.status = "运行中"; activeUniverse.value.statusKey = "running"; }
function completeUniverse() { activeUniverse.value.status = "已完结，只读"; activeUniverse.value.statusKey = "complete"; dialog.value = "completed"; }
function deleteUniverse() { universes.value = universes.value.filter((item) => item.id !== activeUniverse.value.id); activeUniverse.value = universes.value[0]; dialog.value = null; navigate("shelf"); }
function statusIcon(status) { return status === "waiting" ? Pause : status === "complete" ? Check : status === "offline" || status === "paused" ? Clock3 : Play; }
</script>

<template>
  <div class="archive-shell">
    <a class="skip-link" href="#main-content">跳到主要内容</a><div class="star-field" aria-hidden="true"></div>
    <header class="site-header"><button class="brand" type="button" @click="navigate('home')"><span class="brand-mark"><Archive :size="18" /></span><span><b>IRISA</b><small>平行宇宙档案馆</small></span></button><nav class="site-nav" aria-label="主导航"><button :class="{ active: view === 'home' }" type="button" @click="navigate('home')"><Archive :size="16" /> 档案馆</button><button :class="{ active: view === 'shelf' }" type="button" @click="navigate('shelf')"><Library :size="16" /> 宇宙书架</button><button :class="{ active: view === 'court' }" type="button" @click="navigate('court')"><Scale :size="16" /> 人生决策法庭</button><button :class="{ active: view === 'polarizer' }" type="button" @click="navigate('polarizer')"><Target :size="16" /> 偏见偏振器</button></nav><div class="header-actions"><button class="round-button" aria-label="查看叙事说明" type="button" @click="showNotice = !showNotice"><Info :size="18" /></button><button class="mobile-toggle" aria-label="打开导航" type="button" @click="mobileMenuOpen = !mobileMenuOpen"><Menu :size="19" /></button><span class="profile">F</span></div></header>
    <aside v-if="mobileMenuOpen" class="mobile-nav" aria-label="移动导航"><button type="button" @click="navigate('home')">档案馆</button><button type="button" @click="navigate('shelf')">宇宙书架</button><button type="button" @click="navigate('court')">人生决策法庭</button><button type="button" @click="navigate('polarizer')">个人偏见偏振器</button></aside>
    <div v-if="showNotice" class="notice" role="status"><Info :size="16" /> 这里是虚构的平行宇宙叙事，不代表现实经历、预测或人生建议。<button aria-label="关闭说明" type="button" @click="showNotice = false"><X :size="16" /></button></div>

    <main id="main-content">
      <section v-if="view === 'home'" class="entry-page"><div class="entry-architecture" aria-hidden="true"><i class="entry-arch arch-one"></i><i class="entry-arch arch-two"></i><i class="entry-arch arch-three"></i></div><div class="entry-copy"><p class="eyebrow">IRISA ARCHIVE · PRIVATE READING ROOM</p><h1>把没有发生的选择，<em>留在一座可回看的档案馆。</em></h1><p>这里保存虚构的平行宇宙叙事。先整理真实选择或判断方式，再决定是否打开一条独立时间线。</p><button class="primary-button" type="button" @click="navigate('shelf')"><Library :size="17" /> 进入宇宙书架</button></div><section class="entry-routes" aria-label="档案馆入口"><button class="entry-route" type="button" @click="navigate('shelf')"><Library :size="21" /><span><small>ARCHIVE</small><b>宇宙书架</b><em>浏览、继续或回看已经建立的时间线。</em></span><ArrowRight :size="18" /></button><button class="entry-route" type="button" @click="navigate('court')"><Scale :size="21" /><span><small>PREPARATION 01</small><b>人生决策法庭</b><em>把一段真实选择整理成经过确认的决策档案。</em></span><ArrowRight :size="18" /></button><button class="entry-route" type="button" @click="navigate('polarizer')"><Target :size="21" /><span><small>PREPARATION 02</small><b>个人偏见偏振器</b><em>检视命题的依据、边界、反例和更新条件。</em></span><ArrowRight :size="18" /></button></section><p class="entry-disclaimer"><ShieldCheck :size="15" /> 开始前请记住：宇宙内容不是现实重建、预测或建议。</p></section>

      <section v-else-if="view === 'shelf'" class="shelf-page"><button class="back-link" type="button" @click="navigate('home')"><ArrowLeft :size="16" /> 返回档案馆</button><div class="shelf-intro"><div><p class="eyebrow">PRIVATE COLLECTION · {{ universes.length }} UNIVERSES</p><h1>每一条时间线，<em>都是一册独立档案。</em></h1><p class="intro-copy">书脊只记录宇宙编号、名称和状态。抽出一本，进入它已经发生的反事实经历。</p></div></div><div class="shelf-toolbar"><span>馆藏宇宙 · 按最近活动排序</span><span class="shelf-line"></span><span><BookOpen :size="15" /> 正在阅读 {{ activeUniverse ? 1 : 0 }} 册</span></div><div class="library-chamber"><div class="library-window" aria-hidden="true"></div><div class="library-arch arch-left" aria-hidden="true"></div><div class="library-arch arch-right" aria-hidden="true"></div><div class="bookshelf" aria-label="宇宙书架"><span v-for="index in 5" :key="`before-${index}`" class="library-volume" :class="`volume-${String.fromCharCode(96 + index)}`" aria-hidden="true"></span><button v-for="universe in universes" :key="universe.id" class="book" :class="[`cover-${universe.cover}`, { complete: universe.statusKey === 'complete' }]" type="button" @click="openUniverse(universe)"><span class="book-band"></span><span class="book-stamp">IRISA</span><span class="book-number">{{ universe.id }} 号宇宙</span><span class="book-title">{{ universe.title }}</span><span class="book-status"><component :is="statusIcon(universe.statusKey)" :size="12" /> {{ universe.status }}</span></button><button class="book add-book" type="button" @click="beginCreate('future', 'shelf')"><Plus :size="20" /><span>建立新的时间线</span></button></div></div><section class="shelf-note"><FolderOpen :size="18" /><div><b>档案使用边界</b><p>创建时只读取你明确授权的资料。后续现实资料不会改写宇宙已经发生的经历。</p></div><button type="button" @click="showNotice = true">了解叙事规则 <ArrowRight :size="15" /></button></section></section>

      <section v-else-if="view === 'court'" class="antechamber-page court-page"><button class="back-link" type="button" @click="navigate('home')"><ArrowLeft :size="16" /> 返回档案馆</button><div class="game-hero"><span class="game-seal"><Scale :size="26" /></span><div><p class="eyebrow">PREPARATION 01 · DECISION COURT</p><h1>人生决策法庭</h1><p>一局只围绕一个真实选择。五个角色帮助你区分事实、叙述、评价与推测，但不会替你判定哪条路更好。</p></div></div><div class="court-layout"><article class="case-ledger"><div class="panel-heading"><span>案件卷宗</span><small>点击案件查看内容，再开始或继续三阶段庭审</small></div><button v-for="item in sourceCases" :key="item.id" class="ledger-case" :class="{ selected: selectedSource === item.id }" type="button" @click="openCase(item)"><span>CASE {{ item.id.replace('court-', '') }}</span><b>{{ item.title }}</b><small>{{ item.time }} · 现实中 {{ item.actual }}</small><em>{{ item.courtComplete ? '已完成庭审' : '点击查看卷宗' }}</em></button><button class="new-case" type="button" @click="caseFormOpen = !caseFormOpen"><Plus :size="17" /> {{ caseFormOpen ? '收起开案表' : '开立一个新案件' }}</button><form v-if="caseFormOpen" class="case-form" @submit.prevent="saveCase"><label>案件标题<input v-model.trim="caseForm.title" required placeholder="例如：是否接受新的工作机会" /></label><label>选择时间<input v-model.trim="caseForm.time" required placeholder="例如：2025 年 4 月" /></label><label>现实中实际走过的路<input v-model.trim="caseForm.actual" required placeholder="例如：继续留在原团队" /></label><label>当时没有走的可行路径<input v-model.trim="caseForm.alternative" required placeholder="例如：加入创业团队" /></label><label>已知事实和现实限制<textarea v-model.trim="caseForm.facts" placeholder="补充当时的资源、责任、限制或关键事实"></textarea></label><button class="primary-button" type="submit">保存案件 <Check :size="16" /></button></form></article><article v-if="!courtSessionOpen" class="court-brief"><p class="eyebrow">CASE REVIEW</p><h2>{{ selectedCaseData.title }}</h2><dl><div><dt>选择时点</dt><dd>{{ selectedCaseData.time }}</dd></div><div><dt>现实路径</dt><dd>{{ selectedCaseData.actual }}</dd></div><div><dt>可行的未选路径</dt><dd>{{ selectedCaseData.alternative || '尚未补充' }}</dd></div></dl><p>开庭后会依次经过事实、路径、判断三个阶段。每个阶段都可以继续追问，也可以保留不确定性。</p><button class="primary-button" type="button" @click="startCourt()"><Scale :size="16" /> {{ selectedCaseData.courtComplete ? '继续查看庭审' : '开始审理此案件' }}</button></article><article v-else class="court-session"><div class="stage-tabs"><button v-for="(stage, index) in courtStages" :key="stage.name" :class="{ active: courtStage === index, complete: courtStageAccepted[index] }" type="button" @click="courtStage = index"><span>0{{ index + 1 }}</span>{{ stage.name }}<Check v-if="courtStageAccepted[index]" :size="14" /></button></div><div class="session-heading"><p class="eyebrow">阶段 {{ courtStage + 1 }} / 3 · {{ courtStages[courtStage].name }}</p><h2>{{ courtStages[courtStage].title }}</h2><p>{{ courtStages[courtStage].goal }}</p></div><div class="role-notes"><article><b>过去的你</b><span>追问当时的初心和自我理解。</span></article><article><b>悲观主义者</b><span>指出脆弱环节和不可逆代价。</span></article><article><b>机会主义者</b><span>寻找被忽略的机会和替代路径。</span></article><article><b>审计员</b><span>核对事实、限制和资料空白。</span></article><article><b>书记员</b><span>整理共识、争议和仍待确认内容。</span></article></div><div class="court-question"><span>书记员当前记录的问题</span><blockquote>{{ courtStages[courtStage].question }}</blockquote><textarea v-model="courtResponse" placeholder="用你的话回应。也可以写“我不确定”，保留这项空白。"></textarea><div class="session-actions"><button class="secondary-button" type="button" @click="continueCourtStage">继续当前阶段</button><button class="primary-button" type="button" @click="acceptCourtStage">{{ courtStage === 2 ? '确认卷宗并结案' : '接受整理，进入下一阶段' }} <ArrowRight :size="16" /></button></div><p v-if="courtStageContinued" class="inline-note">书记员已记录你的补充。你可以继续回应，或接受当前整理。</p></div></article></div></section>

      <section v-else-if="view === 'polarizer'" class="antechamber-page polarizer-page"><button class="back-link" type="button" @click="navigate('home')"><ArrowLeft :size="16" /> 返回档案馆</button><div class="game-hero"><span class="game-seal"><Target :size="26" /></span><div><p class="eyebrow">PREPARATION 02 · BIAS POLARIZER</p><h1>个人偏见偏振器</h1><p>反方只攻击命题、依据和推理，不攻击你本人。结局不是辩赢，而是形成一个有范围、有反例的判断。</p></div></div><div v-if="!polarizerSessionOpen" class="polarizer-start"><article class="belief-card"><span>当前命题 · {{ polarizerClaimType }}</span><blockquote>“{{ polarizerClaim }}”</blockquote><p>命题可以是核心信念、情境判断，或一个尚不确定、希望被检验的说法。</p><button class="text-action" type="button" @click="dialog = 'materials'"><FileText :size="15" /> 查看已确认材料 <ArrowRight :size="15" /></button></article><article class="polarizer-intro"><p class="eyebrow">第一步 · 先确认命题</p><h2>把命题说清楚，<em>再决定是否更新。</em></h2><label class="claim-editor">我想检验的命题<textarea v-model="polarizerClaim" placeholder="例如：没有足够准备，就不应该离职。"></textarea></label><div class="claim-types"><label v-for="type in ['核心信念', '情境判断', '尚不确定']" :key="type"><input v-model="polarizerClaimType" type="radio" name="claim-type" :value="type" /> {{ type }}</label></div><p>接下来会逐个回应反方的问题。至少写下一次文字回应，或明确承认某个前提尚未验证。</p><ol class="polarizer-guide"><li v-for="(topic, index) in polarizerTopics" :key="topic.name" :class="{ current: index === 0 }"><b>0{{ index + 1 }}</b><span>{{ topic.name }}质疑</span></li></ol><button class="primary-button" type="button" :disabled="!polarizerClaim.trim()" @click="startPolarizer"><Target :size="16" /> 开始一次对打</button></article></div><div v-else class="polarizer-session"><div class="polarizer-progress"><span v-for="(topic, index) in polarizerTopics" :key="topic.name" :class="{ active: polarizerTopic === index, complete: polarizerResponses[index] }">0{{ index + 1 }} {{ topic.name }}</span></div><article class="challenge-panel"><p class="eyebrow">反方质疑 · {{ polarizerTopic + 1 }} / {{ polarizerTopics.length }}</p><h2>{{ polarizerTopics[polarizerTopic].challenge }}</h2><p>请只回应当前这个问题，可以补充经历、缩小范围、指出事实错误，或承认无法回答。</p><textarea v-model="polarizerResponse" placeholder="写下你的回应，至少说明一个依据、边界或不确定之处"></textarea><button class="primary-button" type="button" @click="continuePolarizer">{{ polarizerTopic === polarizerTopics.length - 1 ? '进入结局确认' : '记录回应，继续下一个质疑' }} <ArrowRight :size="16" /></button></article></div></section>

      <section v-else-if="view === 'create'" class="creation-page"><button class="back-link" type="button" @click="navigate(creationReturnView)"><ArrowLeft :size="16" /> 返回上一级</button><div class="creation-heading"><p class="eyebrow">ESTABLISH A NEW TIMELINE</p><h1>从哪里开始这条宇宙？</h1><p>选择起点后，系统只会使用你在确认页明确授权的材料。</p></div><div class="creation-types"><button :class="{ selected: creationType === 'history' }" type="button" @click="creationType = 'history'"><GitBranch :size="23" /><span>历史分叉</span><small>从过去一个真实选择时刻，探索当时没有走过的可行路径。</small><Check v-if="creationType === 'history'" :size="17" /></button><button :class="{ selected: creationType === 'future' }" type="button" @click="creationType = 'future'"><Sparkles :size="23" /><span>未来选择</span><small>从现在开始，填写方向、目标和准备采取的最初行动。</small><Check v-if="creationType === 'future'" :size="17" /></button></div><div v-if="creationType === 'history'" class="setup-panel"><div class="panel-heading"><span>选择一个已确认案件</span><small>历史分叉的时间起点是案件发生时，而不是今天。</small></div><label v-for="item in sourceCases" :key="item.id" class="case-option"><input v-model="selectedSource" :value="item.id" type="radio" /><span><b>{{ item.title }}</b><small>{{ item.time }} · 现实中：{{ item.actual }}</small></span></label><label>当时可行的替代行动<input v-model="form.alternative" placeholder="例如：加入创业团队或提出阶段性合作" /></label><label>起始事实和现实限制<textarea v-model="form.facts" placeholder="会影响分叉成立的关键事实、资源和限制"></textarea></label><button class="primary-button" type="button" @click="openConfirm">继续设定 <ArrowRight :size="16" /></button></div><div v-else class="setup-panel future-form"><label>探索方向<input v-model="form.direction" placeholder="例如：把独立研究做成可持续的工作" /></label><label>目标<textarea v-model="form.goal" placeholder="写下一个具体、可理解的目标"></textarea></label><label>准备采取的最初行动<textarea v-model="form.action" placeholder="尚未发生的行动会标记为“准备开始的行动”"></textarea></label><button class="primary-button" type="button" @click="openConfirm">继续设定 <ArrowRight :size="16" /></button></div></section>

      <section v-else-if="view === 'confirm'" class="confirm-page"><button class="back-link" type="button" @click="navigate('create')"><ArrowLeft :size="16" /> 返回上一步</button><article class="setting-sheet"><header><p class="eyebrow">UNIVERSE SETTING · NUMBER PENDING</p><h1>宇宙设定确认</h1><span class="type-tag">{{ creationType === 'history' ? '历史分叉' : '未来选择' }}</span></header><dl><div><dt>起点</dt><dd>{{ creationType === 'history' ? `${selectedCaseData.time} · ${selectedCaseData.title}` : '现在' }}</dd></div><div><dt>{{ creationType === 'history' ? '替代行动' : '探索方向' }}</dt><dd>{{ creationType === 'history' ? (form.alternative || selectedCaseData.alternative) : form.direction }}</dd></div><div><dt>目标</dt><dd>{{ creationType === 'history' ? '在当时的现实限制下，让未选路径独立发展。' : form.goal }}</dd></div><div><dt>最初行动 / 起始事实</dt><dd>{{ creationType === 'history' ? (form.facts || selectedCaseData.facts) : form.action }}</dd></div></dl><section class="authorization"><div class="panel-heading"><span>本次允许使用的资料</span><small>未勾选的资料不会进入这条宇宙。</small></div><label><input v-model="sourceConsent.court" type="checkbox" /> 决策法庭确认过的案件材料</label><label><input v-model="sourceConsent.polarizer" type="checkbox" /> 偏见偏振器中已确认的判断材料</label><label><input v-model="sourceConsent.profile" type="checkbox" /> 其他已允许的个人资料</label><label class="pace-choice">推演节奏<select v-model="pace"><option value="detailed">细致 · 单次最多 1 个月</option><option value="normal">正常 · 单次最多 6 个月</option><option value="fast">快速 · 单次最多 3 年</option></select></label></section><footer><p><Info :size="15" /> 这是虚构的平行宇宙叙事，不代表现实经历、预测或人生建议。</p><button class="primary-button" type="button" @click="createUniverse"><Sparkles :size="17" /> 确认并开始推演</button></footer></article></section>

      <section v-else-if="view === 'universe'" class="universe-page"><header class="universe-header"><button class="back-link on-dark" type="button" @click="navigate('shelf')"><ArrowLeft :size="16" /> 返回书架</button><div><p class="eyebrow">{{ activeUniverse.id }} 号宇宙 · {{ activeUniverse.type }}</p><h1>{{ activeUniverse.title }}</h1><p>{{ activeUniverse.origin }}</p></div><div class="universe-tools"><span class="status-pill" :class="activeUniverse.statusKey"><component :is="statusIcon(activeUniverse.statusKey)" :size="14" /> {{ activeUniverse.status }}</span><button class="round-button" aria-label="打开宇宙操作" type="button" @click="dialog = 'universe-actions'"><MoreHorizontal :size="19" /></button></div></header><div class="reading-layout"><aside class="timeline"><div class="timeline-head"><span>事件时间线</span><button class="mobile-timeline" type="button" @click="drawerOpen = true"><Menu :size="17" /> 浏览</button></div><div class="timeline-items"><button v-for="event in activeUniverse.events" :key="event.id" :class="{ selected: activeEventId === event.id, pending: event.pending }" type="button" @click="activeEventId = event.id"><i></i><span><small>{{ event.time }}</small><b>{{ event.title }}</b></span></button></div><footer><button type="button" @click="sourcesOpen = true"><FileText :size="15" /> 资料来源</button><button type="button" @click="supplementalOpen = true"><Plus :size="15" /> 补充当前情况</button></footer></aside><article class="archive-paper"><button class="state-summary" type="button" @click="stateOpen = !stateOpen"><span>当前状态</span><b>{{ activeUniverse.state }}</b><ChevronRight :size="16" :class="{ rotated: stateOpen }" /></button><div v-if="stateOpen" class="state-detail"><b>已确认的当前事实</b><p>{{ activeUniverse.state }}</p></div><div class="paper-content"><p class="event-time">{{ activeEvent.time }}</p><h2>{{ activeEvent.title }}</h2><p class="event-body">{{ activeEvent.body }}</p><div v-if="activeEvent.action" class="event-action"><span>我的行动</span><p>{{ activeEvent.action }}</p></div></div><footer class="paper-footer"><span>EVENT {{ activeEvent.id.replace('evt-', '').toUpperCase() }}</span><span>宇宙内已确认经历</span></footer></article></div><section v-if="activeEvent.pending" class="decision-zone"><div v-if="!decisionMode" class="control-choice"><div><p class="eyebrow">TIMELINE PAUSED</p><h2>这件事还没有落定。</h2><p>选择由谁在这条时间线中采取行动。系统不会预告任何选择的后果。</p></div><div class="control-cards"><button type="button" @click="decisionMode = 'intervene'"><span class="control-icon"><Sparkles :size="20" /></span><b>我来介入</b><small>查看可执行的行动</small></button><button type="button" @click="chooseParallel"><span class="control-icon"><Bot :size="20" /></span><b>让平行的我决定</b><small>依据既有经历自行行动</small></button></div></div><div v-else class="action-deck"><div class="deck-head"><button type="button" @click="decisionMode = null"><ArrowLeft :size="16" /> 返回</button><span>选择一张行动卡，再确认</span></div><div class="cards-wrap"><button class="card-nudge" aria-label="上一个行动" type="button" @click="actionIndex = Math.max(0, actionIndex - 1)"><ChevronLeft :size="18" /></button><article class="action-card"><span>行动 {{ String(actionIndex + 1).padStart(2, '0') }} / 04</span><h3>{{ actionCards[actionIndex].title }}</h3><p>{{ actionCards[actionIndex].text }}</p><textarea v-if="actionCards[actionIndex].custom" v-model="customAction" placeholder="写下当前可执行的行动"></textarea></article><button class="card-nudge" aria-label="下一个行动" type="button" @click="actionIndex = Math.min(actionCards.length - 1, actionIndex + 1)"><ChevronRight :size="18" /></button></div><div class="deck-footer"><button class="deck-dot" v-for="(_, index) in actionCards" :key="index" :class="{ active: actionIndex === index }" :aria-label="`选择行动 ${index + 1}`" type="button" @click="actionIndex = index"></button><button class="confirm-action" type="button" @click="confirmAction">确认此行动 <Check :size="16" /></button></div></div></section><section v-else class="continue-zone"><p><Clock3 :size="16" /> 当前时间线停在 {{ activeUniverse.currentTime }}</p><div><button v-if="activeUniverse.statusKey !== 'complete'" class="secondary-button" type="button" @click="offlineOpen = true">离线推演</button><button v-if="activeUniverse.statusKey !== 'complete'" class="primary-button" type="button" @click="continueSimulation"><Play :size="16" /> 继续推演一个事件</button></div></section></section>
      <section v-else class="universe-page"></section>
    </main>

    <div v-if="drawerOpen" class="timeline-drawer"><div><button aria-label="关闭时间线" type="button" @click="drawerOpen = false"><X :size="20" /></button><p>事件时间线</p><button v-for="event in activeUniverse.events" :key="event.id" type="button" @click="activeEventId = event.id; drawerOpen = false"><small>{{ event.time }}</small>{{ event.title }}</button></div></div>
    <div v-if="selectedCase" class="dialog-backdrop" role="presentation" @click.self="selectedCase = null"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭卷宗" type="button" @click="selectedCase = null"><X :size="18" /></button><p class="eyebrow">CASE {{ selectedCase.id.replace('court-', '') }} · {{ selectedCase.status }}</p><h2>{{ selectedCase.title }}</h2><dl><div><dt>发生时间</dt><dd>{{ selectedCase.time }}</dd></div><div><dt>现实路径</dt><dd>{{ selectedCase.actual }}</dd></div><div><dt>未选路径</dt><dd>{{ selectedCase.alternative }}</dd></div><div><dt>已知事实</dt><dd>{{ selectedCase.facts || '卷宗空白' }}</dd></div></dl><button class="primary-button" type="button" @click="startCourt(selectedCase)"><Scale :size="16" /> 进入庭审</button></article></div>
    <div v-if="dialog === 'materials'" class="dialog-backdrop" role="presentation" @click.self="dialog = null"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭材料" type="button" @click="dialog = null"><X :size="18" /></button><p class="eyebrow">POLARIZER MATERIALS · CONFIRMED</p><h2>已确认材料</h2><p class="dialog-hint">档案馆只会参考你明确确认过的判断，不会把反方推测写成你的画像。</p><ul class="materials-list"><li><Check :size="15" /> 你认为准备程度会影响职业风险判断。</li><li><Check :size="15" /> 你愿意在出现具体事实时重新检验判断。</li></ul><button class="primary-button" type="button" @click="dialog = null; startPolarizer()"><Target :size="16" /> 继续检验这条判断</button></article></div>
    <div v-if="dialog === 'polarizer-finish'" class="dialog-backdrop" role="presentation"><article class="dialog-panel" role="dialog" aria-modal="true"><p class="eyebrow">POLARIZER · FINAL POSITION</p><h2>你准备如何保留这条判断？</h2><p class="dialog-hint">最终立场只描述你目前愿意怎么使用命题，不证明它是普遍真理。</p><div class="stance-options"><label v-for="stance in ['继续坚持', '承认边界', '修正判断', '放弃命题', '暂不确定']" :key="stance"><input v-model="polarizerStance" type="radio" name="stance" :value="stance" /> {{ stance }}</label></div><label class="authorization-line"><input v-model="polarizerAuthorized" type="checkbox" /> 允许档案馆在相关场景中参考这份材料</label><button class="primary-button" type="button" :disabled="!polarizerStance" @click="savePolarizerResult">保存最终立场 <Check :size="16" /></button></article></div>
    <div v-if="dialog === 'universe-actions'" class="dialog-backdrop" role="presentation" @click.self="dialog = null"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭宇宙操作" type="button" @click="dialog = null"><X :size="18" /></button><p class="eyebrow">UNIVERSE {{ activeUniverse.id }} · OPERATIONS</p><h2>宇宙操作</h2><div class="operation-list"><button type="button" @click="dialog = null; sourcesOpen = true"><FileText :size="16" /> 查看本宇宙资料来源</button><button v-if="activeUniverse.statusKey === 'paused'" type="button" @click="dialog = null; resumeUniverse()"><Play :size="16" /> 恢复宇宙</button><button v-else-if="activeUniverse.statusKey !== 'complete' && !offlineRunning" type="button" @click="dialog = null; pauseUniverse()"><Pause :size="16" /> 暂停宇宙</button><button v-if="activeUniverse.statusKey !== 'complete'" type="button" @click="dialog = null; completeUniverse()"><Check :size="16" /> 主动完结宇宙</button><button class="danger-action" type="button" @click="dialog = 'delete-confirm'"><X :size="16" /> 删除宇宙</button></div></article></div>
    <div v-if="dialog === 'delete-confirm'" class="dialog-backdrop" role="presentation"><article class="dialog-panel" role="dialog" aria-modal="true"><p class="eyebrow">IRREVERSIBLE ACTION</p><h2>删除这条宇宙？</h2><p class="dialog-hint">时间线、资料、摘要和离线任务都会一并删除，且无法恢复。</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="dialog = null">取消</button><button class="danger-button" type="button" @click="deleteUniverse">确认删除</button></div></article></div>
    <div v-if="sourcesOpen" class="dialog-backdrop" role="presentation" @click.self="sourcesOpen = false"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭资料来源" type="button" @click="sourcesOpen = false"><X :size="18" /></button><p class="eyebrow">UNIVERSE SOURCES · READ ONLY</p><h2>本宇宙资料来源</h2><ul class="materials-list"><li v-for="source in activeUniverse.sources" :key="source"><ShieldCheck :size="15" /> {{ source }}</li></ul><p class="dialog-hint">资料授权只影响后续推演，不会改写宇宙已经发生的经历。</p></article></div>
    <div v-if="supplementalOpen" class="dialog-backdrop" role="presentation" @click.self="supplementalOpen = false"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭补充事实" type="button" @click="supplementalOpen = false"><X :size="18" /></button><p class="eyebrow">ADD CURRENT FACT</p><h2>补充当前情况</h2><p class="dialog-hint">只填写过去一直存在但此前未被提及的宇宙事实。确认后从当前节点起影响后续推演。</p><textarea class="dialog-textarea" v-model="supplementalText" placeholder="例如：当前项目已经获得一个稳定的试用客户。"></textarea><button class="primary-button" type="button" @click="addCurrentFact">确认写入当前状态 <Check :size="16" /></button></article></div>
    <div v-if="offlineOpen" class="dialog-backdrop" role="presentation" @click.self="offlineOpen = false"><article class="dialog-panel" role="dialog" aria-modal="true"><button class="dialog-close" aria-label="关闭离线推演" type="button" @click="offlineOpen = false"><X :size="18" /></button><p class="eyebrow">OFFLINE SIMULATION</p><h2>设置离线推演</h2><p class="dialog-hint">任务由你主动启动，最多推进设定步数；遇到重大决策、缺少资料或异常会提前停止。</p><label class="step-input">最大事件步数<input v-model.number="offlineSteps" type="number" min="1" max="8" /></label><button class="primary-button" type="button" @click="startOffline">启动离线推演 <Play :size="16" /></button></article></div>
    <div v-if="dialog === 'court-complete' || dialog === 'polarizer-saved' || dialog === 'fact-saved' || dialog === 'completed'" class="dialog-backdrop" role="presentation" @click.self="dialog = null"><article class="dialog-panel compact-dialog" role="dialog" aria-modal="true"><Check :size="24" class="success-mark" /><h2>{{ dialog === 'court-complete' ? '案件已结案' : dialog === 'polarizer-saved' ? '认知档案已保存' : dialog === 'fact-saved' ? '当前状态已更新' : '宇宙已完结' }}</h2><p class="dialog-hint">{{ dialog === 'court-complete' ? '卷宗以你最新确认的内容为准，角色的分析仍保留为讨论痕迹。' : dialog === 'polarizer-saved' ? '只有你确认的命题、范围和最终立场会作为可靠判断材料。' : dialog === 'fact-saved' ? '这项事实只会影响当前节点之后的推演。' : '该宇宙现在是只读状态，仍可浏览时间线和资料来源。' }}</p><button class="primary-button" type="button" @click="dialog = null">知道了</button></article></div>
  </div>
</template>
